"""Decide which files in a project tree are excluded by its .packignore files.

This is a pure-Python reimplementation of `packignore`, the legacy exclusion
engine. docs/PACKIGNORE.md describes the basics; the rules below are what the
engine actually does, including the parts the docs leave out.

Reading .packignore files
    Lines are split with str.splitlines() (so \\r, \\v, \\f, \\x1c-\\x1e, \\x85,
    \\u2028 and \\u2029 all end a line) and stripped with str.strip(). Empty
    lines and lines starting with ";" are skipped. "#" is NOT a comment.
    A leading "!" negates the rest of the line (which is not stripped again).
    There are no escapes and no character classes: "\\" and "[" are literal.

Patterns
    A trailing "/" makes the pattern match directories only. Leading "/"s
    are dropped; if the pattern had one, or still contains a "/", it is
    anchored to the directory holding the .packignore, otherwise it matches
    a name at any depth below it. A path segment of exactly "**" matches zero
    or more segments; elsewhere "*" (including "**", "***", ...) matches any
    run of characters within a segment and "?" exactly one character.

Deciding a file
    Every level of the file's path (each ancestor directory, then the file
    itself) is checked. The deepest level that any rule matches decides.
    Among the rules matching that level, the winner is the one from the
    deepest .packignore; then the one with the most literal characters
    (anything but "*", "?" and "/"); then the later line. The file is
    excluded if the winner is a positive (non-"!") rule.

    Before any .packignore rule, two implicit file-level rules exclude
    executable files (any x bit) and files whose first line contains
    "@generated". They rank below every real rule, so "!*" overrides them.

    A .packignore inside a directory that is itself excluded is never read.
"""

import os
import re
import stat

_NAME = ".packignore"
_GENERATED = b"@generated"


class _Rule:
    __slots__ = ("negated", "dir_only", "regex", "rank")

    def __init__(self, negated, dir_only, regex, rank):
        self.negated = negated
        self.dir_only = dir_only
        self.regex = regex
        self.rank = rank


def _segment_regex(seg):
    out = []
    for ch in seg:
        if ch == "*":
            if not out or out[-1] != "[^/]*":
                out.append("[^/]*")
        elif ch == "?":
            out.append("[^/]")
        else:
            out.append(re.escape(ch))
    return "".join(out)


def _compile(line, depth, index):
    """Turn one stripped, non-comment line into a _Rule, or None."""
    negated = line.startswith("!")
    if negated:
        line = line[1:]
    literal = sum(1 for ch in line if ch not in "*?/")
    dir_only = line.endswith("/")
    body = line.rstrip("/")
    anchored = body.startswith("/") or "/" in body.strip("/")
    body = body.lstrip("/")
    if not body:
        return None
    parts = []
    if not anchored:
        parts.append("(?:/[^/]+)*")
    for seg in body.split("/"):
        if seg == "**":
            parts.append("(?:/[^/]+)*")
        else:
            parts.append("/" + _segment_regex(seg))
    regex = re.compile("".join(parts), re.DOTALL)
    return _Rule(negated, dir_only, regex, (depth, literal, index))


def _read_rules(path, depth):
    with open(path, "rb") as f:
        text = f.read().decode("utf-8")
    rules = []
    for index, line in enumerate(text.splitlines()):
        line = line.strip()
        if not line or line.startswith(";"):
            continue
        rule = _compile(line, depth, index)
        if rule is not None:
            rules.append(rule)
    return rules


def _first_line_generated(path):
    tail = b""
    with open(path, "rb") as f:
        while True:
            chunk = f.read(65536)
            if not chunk:
                return False
            nl = chunk.find(b"\n")
            if nl >= 0:
                return _GENERATED in tail + chunk[:nl]
            tail = (tail + chunk)[-(len(_GENERATED) - 1):]
            if _GENERATED in tail + chunk:
                return True


def _implicitly_excluded(path):
    if os.stat(path).st_mode & (stat.S_IXUSR | stat.S_IXGRP | stat.S_IXOTH):
        return True
    return _first_line_generated(path)


def _decide(scopes, rel, is_dir):
    """Return True/False if any rule matches `rel` itself, else None.

    `scopes` is a list of (base, rules) for the .packignore files that apply,
    where `base` is the holding directory relative to root ("" for root).
    """
    best = None
    for base, rules in scopes:
        if base:
            if not rel.startswith(base + "/"):
                continue
            target = "/" + rel[len(base) + 1:]
        else:
            target = "/" + rel
        for rule in rules:
            if rule.dir_only and not is_dir:
                continue
            if best is not None and rule.rank < best.rank:
                continue
            if rule.regex.fullmatch(target):
                best = rule
    if best is None:
        return None
    return not best.negated


